<script setup>
import {t} from './i18n.js';
import SnmpSecurity from './SnmpSecurity.vue';
defineProps({poll:Object,secret:Object,hasSecret:Boolean,requiredSecret:Boolean,responder:Boolean});
</script>
<template><div>
<p v-if="responder" class="form-note">{{t('Dieses SNMP-Ziel wird nur für die authentifizierte Senderprüfung verwendet. Die reguläre Hardwareabfrage bleibt Redfish. Die Prüfung verwendet die separat gespeicherten Trap-Zugangsdaten.')}}</p>
<div class="form-columns"><label>{{t('SNMP-Hostname oder IP-Adresse')}}<input v-model="poll.host" required maxlength="253" placeholder="bmc.example.local" autocomplete="off"></label><label>{{t('SNMP-Agent-Port (UDP)')}}<input v-model="poll.port" type="number" required min="1" max="65535" step="1"></label></div>
<SnmpSecurity v-if="!responder" :security="poll.security" :secret="secret" :has-secret="hasSecret" :required-secret="requiredSecret"/>
<template v-if="!responder"><label>{{t('Hardwareprofil')}}<select v-model="poll.profile"><option value="generic">{{t('Generisch · Verfügbarkeit und System')}}</option><option value="network_generic">{{t('Netzwerk · Generisch')}}</option><option value="dell_idrac">Dell iDRAC</option><option value="hpe_ilo5">HPE iLO</option><option value="synology_dsm">Synology DSM</option><option value="ups_generic">{{t('USV · Generisch (RFC 1628)')}}</option><option value="apc_ups">{{t('APC USV')}}</option><option value="eaton_ups">{{t('Eaton USV')}}</option></select><small>{{t('Der Gesamtzustand gilt für den Bewertungsumfang des gewählten Profils.')}}</small><small v-if="['generic','network_generic'].includes(poll.profile)">{{t('Generisch bewertet SNMP-Erreichbarkeit und Systemidentität. Optionale Sensoren und Inventardaten erweitern die Anzeige; fehlende optionale Bereiche verhindern kein In Ordnung.')}}</small><small v-if="poll.profile==='network_generic'">{{t('Netzwerkschnittstellen werden automatisch erkannt. Nur zuvor aktive Ports melden einen anschließenden Linkverlust. Unbelegte und administrativ deaktivierte Ports erzeugen keinen neuen Linkalarm.')}}</small><small v-if="poll.profile==='synology_dsm'">{{t('DSM: Systempartition, Stromversorgung, Lüfter, Temperaturen, Laufwerke und RAID. DSM unterstützt keine SNMP-Traps.')}}</small><small v-if="['ups_generic','apc_ups','eaton_ups'].includes(poll.profile)">{{t('USV: Batterie- und Versorgungszustände sowie gemeldete Alarmbedingungen. Verfügbare Lade-, Laufzeit- und elektrische Messwerte sind informativ. Das Profil schaltet die USV nicht und löst keine Selbsttests aus.')}}</small></label>
<div v-if="poll.security.version==='v3'" class="form-columns"><label>{{t('Kontextname (optional)')}}<input v-model="poll.context_name" maxlength="32" autocomplete="off"></label><label>{{t('Kontext-Engine-ID (optional, Hex)')}}<input v-model="poll.context_engine_id" maxlength="64" pattern="(?:[0-9a-fA-F]{2}){5,32}" autocomplete="off"></label></div></template>
<div class="form-columns"><label>{{t('Zeitlimit pro Anfrage (Millisekunden)')}}<input v-model="poll.timeout_ms" type="number" required min="100" max="10000" step="1"></label><label>{{t('Wiederholung fehlgeschlagener Anfrage')}}<select v-model="poll.retries"><option :value="0">{{t('Keine Wiederholung')}}</option><option :value="1">{{t('Eine Wiederholung')}}</option></select></label></div>
</div></template>
